fn main() -> Void {
    let n: Int = 6;
    let fromE: Int[] = [5, 5, 2, 3, 3, 1];
    let toE: Int[] = [2, 0, 3, 1, 0, 0];
    let indeg: Int[] = [];
    loop i in 0..n { indeg = indeg + [0]; }
    loop e in 0..length(fromE) { indeg[toE[e]] = indeg[toE[e]] + 1; }
    let order: Int[] = [];
    let done: Int[] = [];
    loop i in 0..n { done = done + [0]; }
    let placed: Int = 0;
    loop pass in 0..n {
        let pick: Int = -1;
        loop v in 0..n {
            if done[v] == 0 && indeg[v] == 0 {
                if pick == -1 { pick = v; }
            }
        }
        if pick == -1 {
            pass = n;
        } else {
            done[pick] = 1;
            order = order + [pick];
            placed = placed + 1;
            loop e in 0..length(fromE) {
                if fromE[e] == pick { indeg[toE[e]] = indeg[toE[e]] - 1; }
            }
        }
    }
    fx {
        print("order:");
        loop i in 0..length(order) { print(" ", order[i]); }
        println("");
        if placed == n { println("acyclic=true placed=", placed); }
        else { println("acyclic=false placed=", placed); }
    }
}

fn main() -> Void {
    let a: Text = "AGGTAB";
    let b: Text = "GXTXAYB";
    let m: Int = string_len(a);
    let n: Int = string_len(b);
    let dp: Int[][] = [];
    loop i in 0..(m + 1) {
        let row: Int[] = [];
        loop j in 0..(n + 1) { row = row + [0]; }
        dp = dp + [row];
    }
    loop i in 1..(m + 1) {
        loop j in 1..(n + 1) {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                if dp[i - 1][j] >= dp[i][j - 1] { dp[i][j] = dp[i - 1][j]; }
                else { dp[i][j] = dp[i][j - 1]; }
            }
        }
    }
    let out: Text = "";
    let i: Int = m;
    let j: Int = n;
    loop step in 0..(m + n) {
        if i > 0 && j > 0 {
            if a[i - 1] == b[j - 1] {
                out = a[i - 1..i] + out;
                i = i - 1;
                j = j - 1;
            } else {
                if dp[i - 1][j] >= dp[i][j - 1] { i = i - 1; } else { j = j - 1; }
            }
        }
    }
    fx {
        println("len=", dp[m][n]);
        println("lcs=", out);
    }
}

fn main() -> Void {
    let lo: Int[] = [5, 1, 12, 2, 20, 13];
    let hi: Int[] = [7, 4, 15, 6, 22, 18];
    loop i in 0..length(lo) {
        loop j in 0..(length(lo) - 1 - i) {
            if lo[j] > lo[j + 1] {
                let tl: Int = lo[j]; lo[j] = lo[j + 1]; lo[j + 1] = tl;
                let th: Int = hi[j]; hi[j] = hi[j + 1]; hi[j + 1] = th;
            }
        }
    }
    let ml: Int[] = [];
    let mh: Int[] = [];
    loop i in 0..length(lo) {
        let k: Int = length(ml);
        if k > 0 && lo[i] <= mh[k - 1] {
            if hi[i] > mh[k - 1] { mh[k - 1] = hi[i]; }
        } else {
            ml = ml + [lo[i]];
            mh = mh + [hi[i]];
        }
    }
    let covered: Int = 0;
    loop i in 0..length(ml) { covered = covered + (mh[i] - ml[i]); }
    fx {
        loop i in 0..length(ml) { println("merged [", ml[i], ",", mh[i], "]"); }
        loop i in 1..length(ml) { println("gap [", mh[i - 1], ",", ml[i], "] size=", ml[i] - mh[i - 1]); }
        println("count=", length(ml), " covered=", covered);
    }
}

fn main() -> Void {
    let cap: Int = 3;
    let keys: Int[] = [];
    let recency: Int[] = [];
    let clock: Int = 0;
    let hits: Int = 0;
    let misses: Int = 0;
    let evicted: Int[] = [];
    let reqs: Int[] = [1, 2, 3, 1, 4, 2, 5, 1, 3, 4];
    loop r in 0..length(reqs) {
        clock = clock + 1;
        let k: Int = reqs[r];
        let at: Int = -1;
        loop i in 0..length(keys) { if keys[i] == k { at = i; } }
        if at != -1 {
            hits = hits + 1;
            recency[at] = clock;
        } else {
            misses = misses + 1;
            if length(keys) == cap {
                let victim: Int = 0;
                loop i in 1..length(keys) { if recency[i] < recency[victim] { victim = i; } }
                evicted = evicted + [keys[victim]];
                keys[victim] = k;
                recency[victim] = clock;
            } else {
                keys = keys + [k];
                recency = recency + [clock];
            }
        }
    }
    fx {
        println("hits=", hits, " misses=", misses);
        print("evicted:");
        loop i in 0..length(evicted) { print(" ", evicted[i]); }
        println("");
        println("resident=", length(keys));
    }
}

@pure
fn findRoot(parent: Int[], x: Int) -> Int {
    let cur: Int = x;
    loop step in 0..length(parent) {
        if parent[cur] != cur { cur = parent[cur]; }
    }
    ret cur;
}
fn main() -> Void {
    let n: Int = 10;
    let parent: Int[] = [];
    loop i in 0..n { parent = parent + [i]; }
    let ea: Int[] = [0, 1, 3, 4, 6, 8, 2];
    let eb: Int[] = [1, 2, 4, 5, 7, 9, 0];
    let merges: Int = 0;
    loop e in 0..length(ea) {
        let ra: Int = findRoot(parent, ea[e]);
        let rb: Int = findRoot(parent, eb[e]);
        if ra != rb {
            if ra < rb { parent[rb] = ra; } else { parent[ra] = rb; }
            merges = merges + 1;
        }
    }
    let roots: Int[] = [];
    let sizes: Int[] = [];
    loop v in 0..n {
        let r: Int = findRoot(parent, v);
        let at: Int = -1;
        loop i in 0..length(roots) { if roots[i] == r { at = i; } }
        if at == -1 { roots = roots + [r]; sizes = sizes + [1]; }
        else { sizes[at] = sizes[at] + 1; }
    }
    let biggest: Int = 0;
    loop i in 1..length(roots) { if sizes[i] > sizes[biggest] { biggest = i; } }
    fx {
        loop i in 0..length(roots) { println("component root=", roots[i], " size=", sizes[i]); }
        println("components=", length(roots), " merges=", merges);
        println("largest root=", roots[biggest], " size=", sizes[biggest]);
    }
}

fn main() -> Void {
    let n: Int = 6;
    let ea: Int[] = [0, 0, 1, 1, 2, 2, 3, 4];
    let eb: Int[] = [1, 2, 2, 3, 3, 4, 5, 5];
    let ew: Int[] = [7, 9, 10, 15, 11, 2, 6, 9];
    let INF: Int = 999999;
    let dist: Int[] = [];
    let prev: Int[] = [];
    let seen: Int[] = [];
    loop i in 0..n { dist = dist + [INF]; prev = prev + [-1]; seen = seen + [0]; }
    dist[0] = 0;
    loop pass in 0..n {
        let u: Int = -1;
        loop v in 0..n {
            if seen[v] == 0 && dist[v] < INF {
                if u == -1 { u = v; } else { if dist[v] < dist[u] { u = v; } }
            }
        }
        if u != -1 {
            seen[u] = 1;
            loop e in 0..length(ea) {
                let f: Int = -1;
                let t: Int = -1;
                if ea[e] == u { f = ea[e]; t = eb[e]; }
                if eb[e] == u { f = eb[e]; t = ea[e]; }
                if f != -1 {
                    if dist[f] + ew[e] < dist[t] {
                        dist[t] = dist[f] + ew[e];
                        prev[t] = f;
                    }
                }
            }
        }
    }
    let path: Int[] = [];
    let cur: Int = 5;
    loop step in 0..n {
        if cur != -1 { path = [cur] + path; cur = prev[cur]; }
    }
    fx {
        loop v in 0..n { println("dist[", v, "]=", dist[v]); }
        print("path:");
        loop i in 0..length(path) { print(" ", path[i]); }
        println("");
        println("cost=", dist[5]);
    }
}

fn main() -> Void {
    let a: Text = "kitten";
    let b: Text = "sitting";
    let m: Int = string_len(a);
    let n: Int = string_len(b);
    let dp: Int[][] = [];
    loop i in 0..(m + 1) {
        let row: Int[] = [];
        loop j in 0..(n + 1) { row = row + [0]; }
        dp = dp + [row];
    }
    loop i in 0..(m + 1) { dp[i][0] = i; }
    loop j in 0..(n + 1) { dp[0][j] = j; }
    loop i in 1..(m + 1) {
        loop j in 1..(n + 1) {
            if a[i - 1] == b[j - 1] {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                let best: Int = dp[i - 1][j - 1];
                if dp[i - 1][j] < best { best = dp[i - 1][j]; }
                if dp[i][j - 1] < best { best = dp[i][j - 1]; }
                dp[i][j] = best + 1;
            }
        }
    }
    let ops: Text[] = [];
    let i: Int = m;
    let j: Int = n;
    loop step in 0..(m + n + 1) {
        if i > 0 || j > 0 {
            if i > 0 && j > 0 && a[i - 1] == b[j - 1] {
                i = i - 1; j = j - 1;
            } else {
                if i > 0 && j > 0 && dp[i][j] == dp[i - 1][j - 1] + 1 {
                    ops = ["sub " + a[i - 1..i] + "->" + b[j - 1..j]] + ops;
                    i = i - 1; j = j - 1;
                } else {
                    if j > 0 && dp[i][j] == dp[i][j - 1] + 1 {
                        ops = ["ins " + b[j - 1..j]] + ops;
                        j = j - 1;
                    } else {
                        ops = ["del " + a[i - 1..i]] + ops;
                        i = i - 1;
                    }
                }
            }
        }
    }
    fx {
        println("distance=", dp[m][n]);
        loop k in 0..length(ops) { println(k, ": ", ops[k]); }
    }
}

fn main() -> Void {
    let xs: Int[] = [1, 3, -1, -3, 5, 3, 6, 7];
    let k: Int = 3;
    let maxes: Int[] = [];
    let dq: Int[] = [];
    loop i in 0..length(xs) {
        loop t in 0..length(dq) {
            let last: Int = length(dq) - 1;
            if last >= 0 && xs[dq[last]] <= xs[i] {
                let nd: Int[] = [];
                loop z in 0..last { nd = nd + [dq[z]]; }
                dq = nd;
            }
        }
        dq = dq + [i];
        if dq[0] <= i - k {
            let nd2: Int[] = [];
            loop z in 1..length(dq) { nd2 = nd2 + [dq[z]]; }
            dq = nd2;
        }
        if i >= k - 1 { maxes = maxes + [xs[dq[0]]]; }
    }
    fx {
        print("maxes:");
        loop i in 0..length(maxes) { print(" ", maxes[i]); }
        println("");
        println("windows=", length(maxes));
    }
}

@pure
fn openerFor(c: Text) -> Text {
    if string_eq(c, ")") { ret "("; }
    if string_eq(c, "]") { ret "["; }
    if string_eq(c, "}") { ret "{"; }
    ret "";
}
fn main() -> Void {
    let samples: Text[] = ["([]{})", "([)]", "((", "", "{[()]}"];
    fx {
        loop s in 0..length(samples) {
            let str: Text = samples[s];
            let stack: Text[] = [];
            let bad: Int = -1;
            loop i in 0..string_len(str) {
                if bad == -1 {
                    let c: Text = str[i..i + 1];
                    if string_eq(c, "(") || string_eq(c, "[") || string_eq(c, "{") {
                        stack = stack + [c];
                    } else {
                        let want: Text = openerFor(c);
                        if string_len(want) > 0 {
                            if length(stack) == 0 { bad = i; }
                            else {
                                let top: Text = stack[length(stack) - 1];
                                if !string_eq(top, want) { bad = i; }
                                else {
                                    let ns: Text[] = [];
                                    loop z in 0..(length(stack) - 1) { ns = ns + [stack[z]]; }
                                    stack = ns;
                                }
                            }
                        }
                    }
                }
            }
            if bad != -1 { println(s, ": bad at ", bad); }
            else {
                if length(stack) != 0 { println(s, ": unclosed ", length(stack)); }
                else { println(s, ": ok"); }
            }
        }
    }
}

fn main() -> Void {
    let wt: Int[] = [3, 4, 5, 2];
    let vl: Int[] = [30, 50, 60, 20];
    let cap: Int = 8;
    let n: Int = length(wt);
    let dp: Int[][] = [];
    loop i in 0..(n + 1) {
        let row: Int[] = [];
        loop c in 0..(cap + 1) { row = row + [0]; }
        dp = dp + [row];
    }
    loop i in 1..(n + 1) {
        loop c in 0..(cap + 1) {
            dp[i][c] = dp[i - 1][c];
            if wt[i - 1] <= c {
                let take: Int = dp[i - 1][c - wt[i - 1]] + vl[i - 1];
                if take > dp[i][c] { dp[i][c] = take; }
            }
        }
    }
    let chosen: Int[] = [];
    let c: Int = cap;
    loop step in 0..n {
        let i: Int = n - step;
        if i > 0 {
            if dp[i][c] != dp[i - 1][c] {
                chosen = [i - 1] + chosen;
                c = c - wt[i - 1];
            }
        }
    }
    let usedW: Int = 0;
    loop k in 0..length(chosen) { usedW = usedW + wt[chosen[k]]; }
    fx {
        println("best=", dp[n][cap]);
        print("items:");
        loop k in 0..length(chosen) { print(" ", chosen[k]); }
        println("");
        println("weight=", usedW, " of ", cap);
    }
}

@pure
fn digitsOf(s: Text) -> Int[] {
    let out: Int[] = [];
    loop i in 0..string_len(s) { out = out + [ord(s[i]) - 48]; }
    ret out;
}
@pure
fn addBig(a: Int[], b: Int[]) -> Int[] {
    let out: Int[] = [];
    let carry: Int = 0;
    let ia: Int = length(a) - 1;
    let ib: Int = length(b) - 1;
    let steps: Int = length(a);
    if length(b) > steps { steps = length(b); }
    loop k in 0..steps {
        let da: Int = 0;
        let db: Int = 0;
        if ia - k >= 0 { da = a[ia - k]; }
        if ib - k >= 0 { db = b[ib - k]; }
        let s: Int = da + db + carry;
        carry = s / 10;
        if s >= 10 { carry = 1; } else { carry = 0; }
        out = [s % 10] + out;
    }
    if carry > 0 { out = [carry] + out; }
    ret out;
}
fn main() -> Void {
    let x: Int[] = digitsOf("987654321987654321");
    let y: Int[] = digitsOf("123456789123456789");
    let s: Int[] = addBig(x, y);
    let txt: Text = "";
    loop i in 0..length(s) { txt = txt + int_to_text(s[i]); }
    fx {
        println("digits=", length(s));
        println("sum=", txt);
    }
}

@pure
fn lowerBound(xs: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(xs);
    loop step in 0..length(xs) {
        if lo < hi {
            let mid: Int = lo + (hi - lo) / 2;
            if xs[mid] < target { lo = mid + 1; } else { hi = mid; }
        }
    }
    ret lo;
}
@pure
fn upperBound(xs: Int[], target: Int) -> Int {
    let lo: Int = 0;
    let hi: Int = length(xs);
    loop step in 0..length(xs) {
        if lo < hi {
            let mid: Int = lo + (hi - lo) / 2;
            if xs[mid] <= target { lo = mid + 1; } else { hi = mid; }
        }
    }
    ret lo;
}
fn main() -> Void {
    let xs: Int[] = [1, 2, 2, 2, 5, 7, 7, 9];
    let probes: Int[] = [2, 7, 3, 0, 9];
    fx {
        loop i in 0..length(probes) {
            let t: Int = probes[i];
            let lb: Int = lowerBound(xs, t);
            let ub: Int = upperBound(xs, t);
            println(t, ": lb=", lb, " ub=", ub, " count=", ub - lb);
        }
    }
}

fn main() -> Void {
    let la: Int[] = [1, 4, 9];
    let lb: Int[] = [2, 3, 10, 11];
    let lc: Int[] = [5, 6];
    let ia: Int = 0;
    let ib: Int = 0;
    let ic: Int = 0;
    let out: Int[] = [];
    let total: Int = length(la) + length(lb) + length(lc);
    let BIG: Int = 999999;
    loop step in 0..total {
        let va: Int = BIG;
        let vb: Int = BIG;
        let vc: Int = BIG;
        if ia < length(la) { va = la[ia]; }
        if ib < length(lb) { vb = lb[ib]; }
        if ic < length(lc) { vc = lc[ic]; }
        if va <= vb && va <= vc { out = out + [va]; ia = ia + 1; }
        else {
            if vb <= vc { out = out + [vb]; ib = ib + 1; }
            else { out = out + [vc]; ic = ic + 1; }
        }
    }
    let sorted: Bool = true;
    loop i in 1..length(out) { if out[i] < out[i - 1] { sorted = false; } }
    fx {
        print("merged:");
        loop i in 0..length(out) { print(" ", out[i]); }
        println("");
        println("len=", length(out), " sorted=", sorted);
    }
}

type Rec { name: Text = ""; score: Int = 0; band: Text = ""; }

@pure
fn bandFor(score: Int) -> Text {
    if score >= 90 { ret "A"; }
    if score >= 75 { ret "B"; }
    if score >= 60 { ret "C"; }
    ret "D";
}
@pure
fn parseScore(raw: Text) -> Int {
    let n: Int = 0;
    let code: Int = 0;
    val(raw, n, code);
    if code != 0 { ret -1; }
    ret n;
}
fn main() -> Void {
    let names: Text[] = ["ada", "bob", "cy", "dee", "eve"];
    let raws: Text[] = ["93", "71", "x8", "60", "88"];
    let recs: Rec[] = [];
    let rejected: Int = 0;
    loop i in 0..length(names) {
        let s: Int = parseScore(raws[i]);
        if s == -1 { rejected = rejected + 1; }
        else { recs = recs + [new Rec { name: names[i], score: s, band: bandFor(s) }]; }
    }
    loop i in 0..length(recs) {
        loop j in 0..(length(recs) - 1 - i) {
            if recs[j].score < recs[j + 1].score {
                let t: Rec = recs[j];
                recs[j] = recs[j + 1];
                recs[j + 1] = t;
            }
        }
    }
    let bands: Text[] = [];
    let counts: Int[] = [];
    loop i in 0..length(recs) {
        let at: Int = -1;
        loop k in 0..length(bands) { if string_eq(bands[k], recs[i].band) { at = k; } }
        if at == -1 { bands = bands + [recs[i].band]; counts = counts + [1]; }
        else { counts[at] = counts[at] + 1; }
    }
    let total: Int = 0;
    loop i in 0..length(recs) { total = total + recs[i].score; }
    fx {
        loop i in 0..length(recs) {
            println(i, ": ", recs[i].name, " ", recs[i].score, " ", recs[i].band);
        }
        loop k in 0..length(bands) { println("band ", bands[k], "=", counts[k]); }
        println("kept=", length(recs), " rejected=", rejected,
                " mean=", formatfloat(total / length(recs), 2));
    }
}
